import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const m=JSON.parse('{"title":"Documents — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"documents-01-overview-and-concepts.md","filePath":"documents-01-overview-and-concepts.md"}'),r={name:"documents-01-overview-and-concepts.md"};function i(s,e,d,c,u,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="documents-—-overview-concepts" tabindex="-1">Documents — Overview &amp; Concepts <a class="header-anchor" href="#documents-—-overview-concepts" aria-label="Permalink to &quot;Documents — Overview &amp; Concepts&quot;">​</a></h1><p><em>What they are, why they matter, and how they fit into Lodestone</em></p><hr><h2 id="what-is-a-document" tabindex="-1">What Is a Document? <a class="header-anchor" href="#what-is-a-document" aria-label="Permalink to &quot;What Is a Document?&quot;">​</a></h2><p>A Document in Lodestone is a written artifact created to provide context, clarity, and narrative support for a Feature. Documents reflect the real-world artifacts product managers are expected to produce — justifications, requirements, communication drafts, go-to-market assets — without requiring you to start from a blank page.</p><p>Every Document in Lodestone is tied to a Feature. Documents don&#39;t exist independently; they exist to explain and support the Feature they belong to.</p><hr><h2 id="why-documents-exist" tabindex="-1">Why Documents Exist <a class="header-anchor" href="#why-documents-exist" aria-label="Permalink to &quot;Why Documents Exist&quot;">​</a></h2><p>Across a single Feature, a PM might be expected to produce a business justification, a set of requirements, acceptance criteria, a customer-facing announcement, and enablement materials for the sales team. Individually, each feels manageable. Collectively, they consume days or weeks of effort — most of it formatting and structuring rather than thinking.</p><p>Lodestone uses AI to generate a strong first draft instantly, so you can spend your time iterating on ideas rather than assembling documents. The goal is to shift effort from blank-page anxiety to meaningful refinement.</p><blockquote><p><strong>Key idea:</strong> AI-generated Documents are starting points, not finished products. All content is fully editable, and you retain full authorship. Lodestone deliberately avoids black-box generation — you always see and control what gets produced.</p></blockquote><hr><h2 id="documents-as-first-class-objects" tabindex="-1">Documents as First-Class Objects <a class="header-anchor" href="#documents-as-first-class-objects" aria-label="Permalink to &quot;Documents as First-Class Objects&quot;">​</a></h2><p>Documents are first-class objects in Lodestone, meaning they can be exported, shared, and used independently of the rest of the platform. This matters because:</p><ul><li>Different teams use different subsets of documents — a team focused on execution needs user stories and UAT plans; a team focused on alignment needs opportunity canvases and PRDs</li><li>Documents are reused across different contexts and audiences</li><li>Each artifact has standalone value outside of Lodestone</li></ul><p>This design means you&#39;re never forced into producing all document types for every Feature — you use what&#39;s useful for your context.</p><hr><h2 id="available-document-types" tabindex="-1">Available Document Types <a class="header-anchor" href="#available-document-types" aria-label="Permalink to &quot;Available Document Types&quot;">​</a></h2><p>Lodestone currently supports eleven document types, organized by their primary job:</p><h3 id="thinking-aids" tabindex="-1">Thinking aids <a class="header-anchor" href="#thinking-aids" aria-label="Permalink to &quot;Thinking aids&quot;">​</a></h3><p>These help you clarify reasoning, articulate tradeoffs, and build a shared understanding of what you&#39;re building and why.</p><table tabindex="0"><thead><tr><th>Document</th><th>Purpose</th></tr></thead><tbody><tr><td>Opportunity Canvas</td><td>A structured one-pager capturing the problem, solution, value, and risks for a Feature</td></tr><tr><td>Product Requirements Document (PRD)</td><td>A detailed description of what needs to be built and why</td></tr></tbody></table><h3 id="delivery-artifacts" tabindex="-1">Delivery artifacts <a class="header-anchor" href="#delivery-artifacts" aria-label="Permalink to &quot;Delivery artifacts&quot;">​</a></h3><p>These support execution and handoff to engineering, QA, and other teams.</p><table tabindex="0"><thead><tr><th>Document</th><th>Purpose</th></tr></thead><tbody><tr><td>User Stories</td><td>Bite-sized descriptions of functionality from the user&#39;s perspective</td></tr><tr><td>UAT Test Plan</td><td>Acceptance criteria and test scenarios for validating the Feature</td></tr><tr><td>User Guide Documentation</td><td>End-user documentation explaining how to use the Feature</td></tr><tr><td>Prototype Prompt</td><td>A prompt designed to be pasted directly into an AI prototyping tool</td></tr></tbody></table><h3 id="communication-assets" tabindex="-1">Communication assets <a class="header-anchor" href="#communication-assets" aria-label="Permalink to &quot;Communication assets&quot;">​</a></h3><p>These support go-to-market, stakeholder communication, and external announcements.</p><table tabindex="0"><thead><tr><th>Document</th><th>Purpose</th></tr></thead><tbody><tr><td>Customer Email</td><td>A direct communication to customers about the Feature</td></tr><tr><td>Company Blog Post</td><td>A long-form external post announcing or explaining the Feature</td></tr><tr><td>Twitter Posts</td><td>Short-form social content for X/Twitter</td></tr><tr><td>Instagram Posts</td><td>Visual-first social content for Instagram</td></tr><tr><td>LinkedIn Posts</td><td>Professional social content for LinkedIn</td></tr></tbody></table><hr><h2 id="where-documents-live" tabindex="-1">Where Documents Live <a class="header-anchor" href="#where-documents-live" aria-label="Permalink to &quot;Where Documents Live&quot;">​</a></h2><p>Documents live on the Feature Detail page, which you access by clicking a Feature name in the backlog. From there you can generate, edit, export, and revisit any Document associated with that Feature.</p><p>Documents are living artifacts — they&#39;re meant to be updated as a Feature evolves, not written once and forgotten. That said, if you choose to regenerate a Document with AI, be aware that regeneration immediately overwrites the existing content with no warning and no recovery path. If you&#39;ve made edits worth keeping, copy them before regenerating.</p><h2 id="the-rich-text-editor" tabindex="-1">The Rich Text Editor <a class="header-anchor" href="#the-rich-text-editor" aria-label="Permalink to &quot;The Rich Text Editor&quot;">​</a></h2><p>All Document types use a <strong>rich text editor</strong> with a formatting toolbar. You can apply formatting directly to document content:</p><ul><li><strong>Bold</strong>, <em>italic</em>, and other inline styles</li><li>Headings and subheadings</li><li>Bullet and numbered lists</li><li>And more</li></ul><p>This means Documents are not just plain text — they can be structured and formatted for direct sharing without additional cleanup. Formatting is preserved when exporting to PDF.</p><hr><h2 id="how-documents-relate-to-features" tabindex="-1">How Documents Relate to Features <a class="header-anchor" href="#how-documents-relate-to-features" aria-label="Permalink to &quot;How Documents Relate to Features&quot;">​</a></h2><ul><li>A Document cannot exist without a Feature</li><li>A Feature can have one Document per type — one Opportunity Canvas, one PRD, one Customer Email, and so on</li><li>Deleting a Feature also deletes all of its associated Documents</li></ul><hr><h2 id="exporting-documents" tabindex="-1">Exporting Documents <a class="header-anchor" href="#exporting-documents" aria-label="Permalink to &quot;Exporting Documents&quot;">​</a></h2><p>All Documents can be exported as <strong>PDFs</strong> or <strong>Markdown files (.md)</strong>. The Markdown export is useful for pasting document content into Notion, Confluence, GitHub, or any other Markdown-friendly tool.</p><p>The Opportunity Canvas has an additional export option — it can be exported as a single <strong>PowerPoint slide</strong>. Opportunity Canvases also appear automatically as an appendix when you export a Roadmap as a PPT presentation.</p><p>Exports are designed to be immediately shareable and presentation-ready, without requiring any additional formatting work.</p><hr><p><em>Next: How-tos &amp; Workflows — step-by-step guides for creating, editing, and exporting Documents.</em></p>',46)])])}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
